{% extends "base.html" %}

{# this head block is not needed if CSS is moved to custom.css #}
{% block head %}
    {{ super() }}
    <style>
    .content-banner-image {
        background-size: cover;
        background-position: center;
        height: 300px;
        margin-bottom: 20px;
        background-image: url('media/og_image.jpg');
    }

